import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { verifyVote } from "../handlers/verifyVote";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePollEntityType } from "../types/SpacePollEntityType";

type Data = Awaited<ReturnType<typeof verifyVote>>;

export function useVerifyVote(
  spacePk: SpacePartition,
  pollSk: SpacePollEntityType,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["verifyVote", spacePk, pollSk],
    queryFn: () => verifyVote(spacePk, pollSk),
    ...options,
  });
}
